package com.skul9x.doctruyen.tts.vieneu

import com.skul9x.doctruyen.utils.DebugLogger
import com.skul9x.doctruyen.utils.LogType
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CopyOnWriteArrayList
import java.util.Locale

/**
 * Diagnostic flag generated by AI Diagnostic Engine.
 */
data class AiDiagnosticFlag(
    val tag: String,
    val description: String,
    val cause: String = ""
)

/**
 * Latency percentage breakdown across pipeline stages.
 */
data class StageLatencyBreakdown(
    val g2pPercent: Float = 0f,
    val g2pDurationMs: Long = 0L,
    val backbonePercent: Float = 0f,
    val backboneDurationMs: Long = 0L,
    val codecPercent: Float = 0f,
    val codecDurationMs: Long = 0L,
    val audioProcessPercent: Float = 0f,
    val audioProcessDurationMs: Long = 0L,
    val totalMeasuredDurationMs: Long = 0L
)

/**
 * Data structure recording detailed timing metrics for an individual TTS chunk.
 */
data class TtsChunkTiming(
    val chunkIndex: Int,
    val totalChunks: Int,
    val textSnippet: String,
    val charCount: Int,
    val phonemeCount: Int,
    val phonemizeDurationMs: Long,
    val inferenceDurationMs: Long,
    val audioDurationMs: Long,
    val rtf: Float,
    val queueDwellTimeMs: Long = 0L,
    val playbackDurationMs: Long = 0L,
    val pauseDurationMs: Long = 0L,
    val starvationDelayMs: Long = 0L,
    val backboneDurationMs: Long = 0L,
    val codecDurationMs: Long = 0L,
    val audioProcessDurationMs: Long = 0L
)

/**
 * Aggregated metrics for an entire TTS playback/reading session.
 */
data class TtsSessionMetrics(
    val storyId: String = "",
    val storyTitle: String = "",
    val timeToFirstAudioMs: Long = 0L,
    val averageRtf: Float = 0f,
    val totalAudioDurationMs: Long = 0L,
    val totalSynthesisDurationMs: Long = 0L,
    val underrunCount: Int = 0,
    val chunks: List<TtsChunkTiming> = emptyList(),
    val deviceProfile: DeviceProfile? = null,
    val startMemory: MemorySnapshot? = null,
    val endMemory: MemorySnapshot? = null,
    val startThermal: ThermalSnapshot? = null,
    val endThermal: ThermalSnapshot? = null,
    val totalChars: Int = 0,
    val babbleRetryCount: Int = 0
)

/**
 * Core timing telemetry engine for VieNeu TTS with AI-oriented self-diagnostic rules.
 * Thread-safe and non-blocking.
 */
object TtsMetricsLogger {

    private const val TAG = "TtsMetrics"

    @Volatile
    var currentSession: TtsSessionMetrics = TtsSessionMetrics()
        private set

    private var sessionStartTimeMs: Long = 0L
    private var preBufferStartTimeMs: Long = 0L
    private var preBufferDurationMs: Long = 0L
    private var firstAudioOutputTimeMs: Long = 0L
    private val chunkTimings = CopyOnWriteArrayList<TtsChunkTiming>()
    private val chunkQueueTimeMap = ConcurrentHashMap<Int, Long>()
    private var underrunCount: Int = 0
    private var babbleRetryCount: Int = 0

    private var initialStoryChars: Int = 0

    @Synchronized
    fun startSession(
        storyId: String = "",
        storyTitle: String = "",
        deviceProfile: DeviceProfile? = null,
        startMemory: MemorySnapshot? = null,
        startThermal: ThermalSnapshot? = null,
        initialStoryChars: Int = 0
    ) {
        sessionStartTimeMs = System.currentTimeMillis()
        preBufferStartTimeMs = sessionStartTimeMs
        preBufferDurationMs = 0L
        firstAudioOutputTimeMs = 0L
        underrunCount = 0
        babbleRetryCount = 0
        this.initialStoryChars = initialStoryChars
        chunkTimings.clear()
        chunkQueueTimeMap.clear()
        currentSession = TtsSessionMetrics(
            storyId = storyId,
            storyTitle = storyTitle,
            deviceProfile = deviceProfile,
            startMemory = startMemory,
            startThermal = startThermal,
            totalChars = initialStoryChars
        )
        val msg = "⏱️ [TTS Session Start] storyId='$storyId', title='$storyTitle'"
        DebugLogger.log(TAG, msg, LogType.TTS_TIMING)
    }

    @Synchronized
    fun startSession(
        storyId: String = "",
        storyTitle: String = "",
        context: android.content.Context?,
        engineThreads: Int = 1,
        quantization: String = "Unknown",
        initialStoryChars: Int = 0
    ) {
        val deviceProfile = DevicePerformanceHelper.getDeviceProfile(context, engineThreads, quantization)
        val startMemory = DevicePerformanceHelper.getMemorySnapshot(context)
        val startThermal = DevicePerformanceHelper.getThermalSnapshot(context)
        startSession(
            storyId = storyId,
            storyTitle = storyTitle,
            deviceProfile = deviceProfile,
            startMemory = startMemory,
            startThermal = startThermal,
            initialStoryChars = initialStoryChars
        )
    }

    @Synchronized
    fun updateActiveQuantization(quantization: String) {
        val oldProfile = currentSession.deviceProfile
        val updatedProfile = oldProfile?.copy(quantization = quantization)
            ?: DeviceProfile(quantization = quantization)
        currentSession = currentSession.copy(deviceProfile = updatedProfile)
        DebugLogger.log(TAG, "🔄 [TtsMetrics] Active session quantization updated to $quantization", LogType.TTS_TIMING)
    }

    @Synchronized
    fun logEngineReload(newPrecision: String) {
        updateActiveQuantization(newPrecision)
        val msg = "🔁 [Engine Reload] Precision switched to $newPrecision. Active session telemetry updated."
        DebugLogger.log(TAG, msg, LogType.TTS_TIMING)
    }

    fun recordPreBufferingStart() {
        preBufferStartTimeMs = System.currentTimeMillis()
    }

    fun recordPreBufferingComplete(bufferedChunks: Int, bufferedDurationMs: Long) {
        val now = System.currentTimeMillis()
        preBufferDurationMs = if (preBufferStartTimeMs > 0L) now - preBufferStartTimeMs else 0L
        val msg = "📦 [Pre-buffering Ready] chunks=$bufferedChunks, duration=${bufferedDurationMs}ms, waitTime=${preBufferDurationMs}ms"
        DebugLogger.log(TAG, msg, LogType.TTS_TIMING)
    }

    @Synchronized
    fun recordBabbleRetry(
        phonemes: String = "",
        retryAttempt: Int = 1,
        burstCount: Int = 0,
        syllableCount: Int = 0,
        reason: String = "excess_bursts"
    ) {
        babbleRetryCount++
        updateSessionSnapshot()
        val msg = "⚠️ [Babble Guard] Retry #$retryAttempt triggered (syllables=$syllableCount, bursts=$burstCount, reason=$reason) for '$phonemes'"
        DebugLogger.log(TAG, msg, LogType.TTS_TIMING)
    }

    fun getBabbleRetryCount(): Int = babbleRetryCount

    fun recordChunkSynthesis(
        chunkIndex: Int,
        totalChunks: Int,
        text: String,
        phonemeCount: Int,
        phonemizeDurationMs: Long,
        inferenceDurationMs: Long,
        audioDurationMs: Long,
        pauseDurationMs: Long = 0L,
        backboneDurationMs: Long = 0L,
        codecDurationMs: Long = 0L,
        audioProcessDurationMs: Long = 0L
    ): TtsChunkTiming {
        val snippet = if (text.length > 40) text.take(40) + "..." else text
        val rtf = if (audioDurationMs > 0) inferenceDurationMs.toFloat() / audioDurationMs else 0f
        
        // Mark enqueue time for dwell time calculation
        chunkQueueTimeMap[chunkIndex] = System.currentTimeMillis()

        val timing = TtsChunkTiming(
            chunkIndex = chunkIndex,
            totalChunks = totalChunks,
            textSnippet = snippet,
            charCount = text.length,
            phonemeCount = phonemeCount,
            phonemizeDurationMs = phonemizeDurationMs,
            inferenceDurationMs = inferenceDurationMs,
            audioDurationMs = audioDurationMs,
            rtf = rtf,
            pauseDurationMs = pauseDurationMs,
            backboneDurationMs = backboneDurationMs,
            codecDurationMs = codecDurationMs,
            audioProcessDurationMs = audioProcessDurationMs
        )
        chunkTimings.add(timing)
        updateSessionSnapshot()

        val logMsg = formatChunkLog(timing)
        DebugLogger.log(TAG, logMsg, LogType.TTS_TIMING)

        return timing
    }

    fun recordPlaybackStart(chunkIndex: Int, starvationDelayMs: Long = 0L) {
        val now = System.currentTimeMillis()
        if (firstAudioOutputTimeMs == 0L) {
            firstAudioOutputTimeMs = now
            val ttft = if (sessionStartTimeMs > 0) now - sessionStartTimeMs else 0L
            updateSessionSnapshot()
            val ttftMsg = "⚡ [TTFT] Time to first audio: ${ttft}ms"
            DebugLogger.log(TAG, ttftMsg, LogType.TTS_TIMING)
        }

        if (starvationDelayMs > 0) {
            recordUnderrun(chunkIndex, starvationDelayMs)
        }

        val queueTime = chunkQueueTimeMap.remove(chunkIndex)
        val dwellTime = if (queueTime != null && queueTime > 0) now - queueTime else 0L

        // Update the timing item in list
        val index = chunkTimings.indexOfFirst { it.chunkIndex == chunkIndex }
        if (index >= 0) {
            val old = chunkTimings[index]
            val updated = old.copy(
                queueDwellTimeMs = dwellTime,
                starvationDelayMs = starvationDelayMs
            )
            chunkTimings[index] = updated
            updateSessionSnapshot()
        }
    }

    fun recordPlaybackComplete(chunkIndex: Int, actualPlaybackDurationMs: Long) {
        val index = chunkTimings.indexOfFirst { it.chunkIndex == chunkIndex }
        if (index >= 0) {
            val old = chunkTimings[index]
            val updated = old.copy(playbackDurationMs = actualPlaybackDurationMs)
            chunkTimings[index] = updated
            updateSessionSnapshot()
        }
    }

    @Synchronized
    fun recordUnderrun(chunkIndex: Int, delayMs: Long) {
        underrunCount++
        updateSessionSnapshot()
        val msg = "⚠️ [Buffer Starvation] Chunk #$chunkIndex delayed by ${delayMs}ms (Underrun count: $underrunCount)"
        DebugLogger.log(TAG, msg, LogType.TTS_TIMING)
    }

    @Synchronized
    fun endSession(
        endMemory: MemorySnapshot? = null,
        endThermal: ThermalSnapshot? = null
    ): TtsSessionMetrics {
        if (endMemory != null || endThermal != null) {
            currentSession = currentSession.copy(
                endMemory = endMemory ?: currentSession.endMemory,
                endThermal = endThermal ?: currentSession.endThermal
            )
        }
        val session = updateSessionSnapshot()
        val summaryMsg = formatSessionSummary(session)
        DebugLogger.log(TAG, summaryMsg, LogType.TTS_TIMING)

        val diagnosticReport = formatAiDiagnosticReport(session)
        DebugLogger.log(TAG, diagnosticReport, LogType.TTS_TIMING)

        return session
    }

    @Synchronized
    fun endSession(context: android.content.Context?): TtsSessionMetrics {
        val endMem = DevicePerformanceHelper.getMemorySnapshot(context)
        val endThermal = DevicePerformanceHelper.getThermalSnapshot(context)
        return endSession(endMemory = endMem, endThermal = endThermal)
    }

    fun formatChunkLog(timing: TtsChunkTiming): String {
        return String.format(
            Locale.US,
            "⚡ [Chunk %d/%d] chars=%d | phonemes=%d | g2p=%dms | infer=%dms | audio=%dms | rtf=%.2fx | pause=%dms | text='%s'",
            timing.chunkIndex + 1,
            timing.totalChunks,
            timing.charCount,
            timing.phonemeCount,
            timing.phonemizeDurationMs,
            timing.inferenceDurationMs,
            timing.audioDurationMs,
            timing.rtf,
            timing.pauseDurationMs,
            timing.textSnippet
        )
    }

    fun formatSessionSummary(session: TtsSessionMetrics): String {
        return String.format(
            Locale.US,
            "📊 [TTS Session Summary]\n" +
            "• Story: %s (%s)\n" +
            "• TTFT (Time to First Audio): %d ms\n" +
            "• Chunks Synthesized: %d\n" +
            "• Avg RTF: %.2fx\n" +
            "• Total Inference Time: %d ms\n" +
            "• Total Audio Duration: %d ms (%.1fs)\n" +
            "• Buffer Underruns: %d",
            session.storyTitle.ifEmpty { "N/A" },
            session.storyId.ifEmpty { "N/A" },
            session.timeToFirstAudioMs,
            session.chunks.size,
            session.averageRtf,
            session.totalSynthesisDurationMs,
            session.totalAudioDurationMs,
            session.totalAudioDurationMs / 1000f,
            session.underrunCount
        )
    }

    fun calculateStagePercentages(session: TtsSessionMetrics): StageLatencyBreakdown {
        val totalG2p = session.chunks.sumOf { it.phonemizeDurationMs }
        val totalBackbone = session.chunks.sumOf { it.backboneDurationMs }
        val totalCodec = session.chunks.sumOf { it.codecDurationMs }
        val totalAudioProcess = session.chunks.sumOf { it.audioProcessDurationMs }

        val totalMeasured = totalG2p + totalBackbone + totalCodec + totalAudioProcess
        if (totalMeasured == 0L) {
            return StageLatencyBreakdown()
        }

        val g2pPercent = (totalG2p.toFloat() / totalMeasured) * 100f
        val backbonePercent = (totalBackbone.toFloat() / totalMeasured) * 100f
        val codecPercent = (totalCodec.toFloat() / totalMeasured) * 100f
        val audioProcessPercent = (totalAudioProcess.toFloat() / totalMeasured) * 100f

        return StageLatencyBreakdown(
            g2pPercent = g2pPercent,
            g2pDurationMs = totalG2p,
            backbonePercent = backbonePercent,
            backboneDurationMs = totalBackbone,
            codecPercent = codecPercent,
            codecDurationMs = totalCodec,
            audioProcessPercent = audioProcessPercent,
            audioProcessDurationMs = totalAudioProcess,
            totalMeasuredDurationMs = totalMeasured
        )
    }

    fun detectAiFlags(session: TtsSessionMetrics): List<AiDiagnosticFlag> {
        val flags = mutableListOf<AiDiagnosticFlag>()

        // 1. [AI_FLAG: SLOW_TTFT]
        if (session.timeToFirstAudioMs > 3500L) {
            flags.add(
                AiDiagnosticFlag(
                    tag = "AI_FLAG: SLOW_TTFT",
                    description = "TTFT = ${session.timeToFirstAudioMs}ms > 3500ms target.",
                    cause = "Pre-warming chưa xong khi bấm Play hoặc chunk đầu tiên quá dài."
                )
            )
        }

        // 2. [AI_FLAG: BUFFER_UNDERRUN]
        if (session.underrunCount > 0) {
            val starvationChunks = session.chunks.filter { it.starvationDelayMs > 0 }
            val starvationDesc = if (starvationChunks.isNotEmpty()) {
                starvationChunks.joinToString(", ") { "Chunk #${it.chunkIndex + 1} trễ ${it.starvationDelayMs}ms" }
            } else {
                "${session.underrunCount} lần khựng"
            }
            flags.add(
                AiDiagnosticFlag(
                    tag = "AI_FLAG: BUFFER_UNDERRUN",
                    description = "Buffer cạn khi đang phát ($starvationDesc).",
                    cause = "Tốc độ tổng hợp chậm hơn tốc độ phát hoặc pre-buffering chưa đủ."
                )
            )
        }

        // 3. [AI_FLAG: CPU_BOUND_RTF_HIGH]
        if (session.averageRtf > 1.0f) {
            flags.add(
                AiDiagnosticFlag(
                    tag = "AI_FLAG: CPU_BOUND_RTF_HIGH",
                    description = String.format(Locale.US, "RTF trung bình = %.2fx > 1.0x.", session.averageRtf),
                    cause = "Thiết bị không đáp ứng được tốc độ realtime, CPU bị nghẽn."
                )
            )
        }

        // 4. [AI_FLAG: THERMAL_THROTTLED]
        val endThermalStatus = session.endThermal?.thermalThrottlingStatus?.uppercase(Locale.US) ?: "NONE"
        val isThermalThrottled = when (endThermalStatus) {
            "SEVERE", "CRITICAL", "EMERGENCY", "SHUTDOWN" -> true
            else -> false
        }
        if (isThermalThrottled) {
            flags.add(
                AiDiagnosticFlag(
                    tag = "AI_FLAG: THERMAL_THROTTLED",
                    description = "Thermal Status đạt mức $endThermalStatus.",
                    cause = "SoC bị quá nhiệt bóp xung inference."
                )
            )
        }

        // 5. [AI_FLAG: MEMORY_LEAK_SUSPECTED]
        if (session.startMemory != null && session.endMemory != null) {
            val nativeDelta = session.endMemory.nativeHeapAllocatedMb - session.startMemory.nativeHeapAllocatedMb
            if (nativeDelta > 50f) {
                flags.add(
                    AiDiagnosticFlag(
                        tag = "AI_FLAG: MEMORY_LEAK_SUSPECTED",
                        description = String.format(Locale.US, "Native Heap delta vượt +%.1fMB.", nativeDelta),
                        cause = "Native tensor hoặc PCM buffers có thể chưa được giải phóng triệt để."
                    )
                )
            }
        }

        // 6. [AI_FLAG: CHUNK_TOO_LONG]
        val longChunks = session.chunks.filter { it.charCount > 120 }
        if (longChunks.isNotEmpty()) {
            val maxLen = longChunks.maxOf { it.charCount }
            flags.add(
                AiDiagnosticFlag(
                    tag = "AI_FLAG: CHUNK_TOO_LONG",
                    description = "Có ${longChunks.size} chunk vượt quá 120 ký tự (lớn nhất: $maxLen chars).",
                    cause = "Độ dài câu quá lớn làm tăng thời gian suy luận và nguy cơ khựng âm thanh."
                )
            )
        }

        // 7. [AI_FLAG: G2P_OVERHEAD]
        val slowG2pChunks = session.chunks.filter { it.phonemizeDurationMs > 50L }
        if (slowG2pChunks.isNotEmpty()) {
            val maxG2p = slowG2pChunks.maxOf { it.phonemizeDurationMs }
            flags.add(
                AiDiagnosticFlag(
                    tag = "AI_FLAG: G2P_OVERHEAD",
                    description = "G2P phonemize vượt quá 50ms (${slowG2pChunks.size} chunks, cao nhất: ${maxG2p}ms).",
                    cause = "Xử lý phiên âm SeaG2P/Regex tốn nhiều thời gian CPU."
                )
            )
        }

        return flags
    }

    fun generateRecommendations(flags: List<AiDiagnosticFlag>): List<String> {
        val recommendations = mutableListOf<String>()
        val flagTags = flags.map { it.tag }.toSet()

        if ("AI_FLAG: SLOW_TTFT" in flagTags) {
            recommendations.add("1. [OPTIMIZE_PREWARM]: Gọi prepareStory() ngay khi mở StoryDetailActivity để đạt TTFT < 1000ms.")
        }
        if ("AI_FLAG: CHUNK_TOO_LONG" in flagTags || "AI_FLAG: SLOW_TTFT" in flagTags) {
            recommendations.add("2. [OPTIMIZE_SEGMENTATION]: Tinh chỉnh SmartTextSegmenter để giới hạn độ dài chunk <= 100 chars, ưu tiên ngắt câu nhỏ hơn.")
        }
        if ("AI_FLAG: BUFFER_UNDERRUN" in flagTags) {
            recommendations.add("3. [OPTIMIZE_PREBUFFER]: Tăng requiredDurationMs của pre-buffering hoặc số lượng chunk đệm trước khi phát âm thanh đối với thiết bị tầm trung.")
        }
        if ("AI_FLAG: CPU_BOUND_RTF_HIGH" in flagTags) {
            recommendations.add("4. [OPTIMIZE_THREADS_QUANTIZATION]: Giảm số threads ONNX hoặc kích hoạt INT8 quantization (q4/q8) để giảm tải CPU.")
        }
        if ("AI_FLAG: THERMAL_THROTTLED" in flagTags) {
            recommendations.add("5. [OPTIMIZE_COOLING]: Chèn khoảng nghỉ ngắn (idle sleep) giữa các lần chunk inference khi phát hiện nhiệt độ tăng cao.")
        }
        if ("AI_FLAG: G2P_OVERHEAD" in flagTags) {
            recommendations.add("6. [OPTIMIZE_G2P_CACHE]: Kích hoạt bộ nhớ đệm từ điển (G2P vocabulary lookup cache) để tránh tính toán lại.")
        }

        return recommendations
    }

    fun formatAiDiagnosticReport(session: TtsSessionMetrics): String {
        val sb = StringBuilder()
        sb.append("========================== 📊 AI PERFORMANCE DIAGNOSTIC ==========================\n")

        // [DEVICE PROFILE]
        sb.append("[DEVICE PROFILE]\n")
        val dp = session.deviceProfile
        if (dp != null) {
            sb.append(String.format(
                Locale.US,
                "• Device: %s %s | SoC: %s (%d Cores) | RAM: %.1fGB Free\n",
                dp.manufacturer,
                dp.model,
                dp.socModel,
                dp.cpuCores,
                dp.availableRamMb / 1024f
            ))
            sb.append(String.format(
                Locale.US,
                "• Runtime Engine: VieNeu ONNX | Threads: %d | Quantization: %s\n",
                dp.engineThreads,
                dp.quantization
            ))
        } else {
            sb.append("• Device Profile: N/A\n")
        }
        sb.append("\n")

        // [SESSION METRICS]
        sb.append("[SESSION METRICS]\n")
        val totalChars = if (session.totalChars > 0) session.totalChars else session.chunks.sumOf { it.charCount }
        val totalAudioSec = session.totalAudioDurationMs / 1000f
        val totalInferSec = session.totalSynthesisDurationMs / 1000f
        val throughput = if (totalInferSec > 0) totalChars / totalInferSec else 0f

        sb.append(String.format(
            Locale.US,
            "• Story: %d chars | %d chunks | Total Speech Duration: %.1fs\n",
            totalChars,
            session.chunks.size,
            totalAudioSec
        ))
        sb.append(String.format(
            Locale.US,
            "• Total Inference Time: %.1fs | Overall RTF: %.2fx (Throughput: %.1f chars/s)\n",
            totalInferSec,
            session.averageRtf,
            throughput
        ))
        sb.append(String.format(
            Locale.US,
            "• TTFT (Time to First Audio): %d ms\n",
            session.timeToFirstAudioMs
        ))
        sb.append(String.format(
            Locale.US,
            "• Buffer Starvations: %d lần\n",
            session.underrunCount
        ))

        // Memory Footprint
        if (session.startMemory != null && session.endMemory != null) {
            val delta = session.endMemory.nativeHeapAllocatedMb - session.startMemory.nativeHeapAllocatedMb
            val leakStatus = if (delta > 50f) "Potential Leak" else "No Leak"
            sb.append(String.format(
                Locale.US,
                "• Memory Footprint: Native Heap: %.0fMB ➔ %.0fMB (Delta: %+.0fMB, %s)\n",
                session.startMemory.nativeHeapAllocatedMb,
                session.endMemory.nativeHeapAllocatedMb,
                delta,
                leakStatus
            ))
        }

        // Thermal Profile
        if (session.startThermal != null && session.endThermal != null) {
            val tempDelta = session.endThermal.batteryTempCelsius - session.startThermal.batteryTempCelsius
            sb.append(String.format(
                Locale.US,
                "• Thermal Profile: %.1f°C ➔ %.1f°C (%+.1f°C) | Throttling: %s\n",
                session.startThermal.batteryTempCelsius,
                session.endThermal.batteryTempCelsius,
                tempDelta,
                session.endThermal.thermalThrottlingStatus
            ))
        }
        sb.append("\n")

        // [LATENCY PROFILING PER STAGE]
        sb.append("[LATENCY PROFILING PER STAGE]\n")
        val stagePercentages = calculateStagePercentages(session)
        sb.append(String.format(
            Locale.US,
            "• G2P Processing:      %5.1f%% tổng thời gian (%d ms)\n",
            stagePercentages.g2pPercent,
            stagePercentages.g2pDurationMs
        ))
        sb.append(String.format(
            Locale.US,
            "• ONNX Backbone:      %5.1f%% tổng thời gian (%d ms)\n",
            stagePercentages.backbonePercent,
            stagePercentages.backboneDurationMs
        ))
        sb.append(String.format(
            Locale.US,
            "• ONNX Decoder Codec: %5.1f%% tổng thời gian (%d ms)\n",
            stagePercentages.codecPercent,
            stagePercentages.codecDurationMs
        ))
        sb.append(String.format(
            Locale.US,
            "• Audio Enqueue/PCM:   %5.1f%% tổng thời gian (%d ms)\n",
            stagePercentages.audioProcessPercent,
            stagePercentages.audioProcessDurationMs
        ))
        sb.append("\n")

        // [ACTIVE AI FLAGS & BOTTLENECK ANALYSIS]
        sb.append("[ACTIVE AI FLAGS & BOTTLENECK ANALYSIS]\n")
        val flags = detectAiFlags(session)
        if (flags.isEmpty()) {
            sb.append("✓ Không phát hiện bottleneck hiệu năng. Hệ thống hoạt động tối ưu.\n")
        } else {
            for (flag in flags) {
                sb.append("⚠️ [${flag.tag}] ${flag.description} (Nguyên nhân: ${flag.cause})\n")
            }
        }
        sb.append("\n")

        // [🎯 AI ACTIONABLE RECOMMENDATIONS]
        sb.append("[🎯 AI ACTIONABLE RECOMMENDATIONS]\n")
        val recommendations = generateRecommendations(flags)
        if (recommendations.isEmpty()) {
            sb.append("✓ Cấu hình hiện tại đạt hiệu năng tốt, không cần thay đổi.\n")
        } else {
            for (rec in recommendations) {
                sb.append("$rec\n")
            }
        }
        sb.append("==================================================================================")

        return sb.toString()
    }

    private fun updateSessionSnapshot(): TtsSessionMetrics {
        val ttft = if (firstAudioOutputTimeMs > 0 && sessionStartTimeMs > 0) {
            firstAudioOutputTimeMs - sessionStartTimeMs
        } else {
            0L
        }

        val totalAudio = chunkTimings.sumOf { it.audioDurationMs }
        val totalInfer = chunkTimings.sumOf { it.inferenceDurationMs }
        val sumChars = chunkTimings.sumOf { it.charCount }
        val effectiveTotalChars = if (initialStoryChars > 0) initialStoryChars else sumChars
        val avgRtf = if (totalAudio > 0) totalInfer.toFloat() / totalAudio else 0f

        val snapshot = currentSession.copy(
            timeToFirstAudioMs = if (currentSession.timeToFirstAudioMs > 0) currentSession.timeToFirstAudioMs else ttft,
            averageRtf = avgRtf,
            totalAudioDurationMs = totalAudio,
            totalSynthesisDurationMs = totalInfer,
            totalChars = effectiveTotalChars,
            underrunCount = underrunCount,
            chunks = ArrayList(chunkTimings),
            babbleRetryCount = babbleRetryCount
        )
        currentSession = snapshot
        return snapshot
    }

    fun getChunkTimings(): List<TtsChunkTiming> = ArrayList(chunkTimings)
}

